//! Shared protocol types and utilities

use anyhow::{Context, Result};
use hmac::{Hmac, Mac};
use serde::{Deserialize, Serialize};
use sha2::Sha256;
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
use uuid::Uuid;

/// Control port for the bore server
pub const CONTROL_PORT: u16 = 7835;

/// Messages sent over the control connection
#[derive(Debug, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ServerMessage {
    /// Sent by the server to initiate authentication challenge
    Challenge(ChallengeMsg),
    /// Sent by the server to acknowledge client hello
    Hello(HelloMsg),
    /// Sent by the server when a new connection arrives on the tunnel port
    Connection(ConnectionMsg),
    /// Sent by the server as a keepalive
    Heartbeat,
    /// Sent by the server when an error occurs
    Error(ErrorMsg),
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ChallengeMsg {
    #[serde(rename = "Challenge")]
    pub id: Uuid,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct HelloMsg {
    #[serde(rename = "Hello")]
    pub port: u16,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ConnectionMsg {
    #[serde(rename = "Connection")]
    pub id: Uuid,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ErrorMsg {
    #[serde(rename = "Error")]
    pub message: String,
}

/// Messages sent by the client over the control connection
#[derive(Debug, Serialize, Deserialize)]
#[serde(untagged)]
pub enum ClientMessage {
    /// Authentication response
    Authenticate(AuthMsg),
    /// Hello message from client requesting a tunnel port
    Hello(HelloMsg),
    /// Accept message when client opens a new proxy connection
    Accept(AcceptMsg),
}

#[derive(Debug, Serialize, Deserialize)]
pub struct AuthMsg {
    #[serde(rename = "Authenticate")]
    pub token: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct AcceptMsg {
    #[serde(rename = "Accept")]
    pub id: Uuid,
}

/// Compute HMAC-SHA256(key=SHA256(secret), msg=challenge_uuid.bytes)
pub fn compute_auth_token(secret: &str, challenge: Uuid) -> String {
    use sha2::Digest;
    let secret_key = Sha256::digest(secret.as_bytes());
    let mut mac = Hmac::<Sha256>::new_from_slice(&secret_key).expect("HMAC can use any key size");
    mac.update(challenge.as_bytes());
    let result = mac.finalize();
    hex::encode(result.into_bytes())
}

/// Verify authentication token
pub fn verify_auth_token(secret: &str, challenge: Uuid, token: &str) -> bool {
    let expected = compute_auth_token(secret, challenge);
    // Constant-time comparison
    expected.len() == token.len() && expected.bytes().zip(token.bytes()).all(|(a, b)| a == b)
}

/// Send a null-terminated JSON message
pub async fn send_msg<T: Serialize, W: AsyncWrite + Unpin>(writer: &mut W, msg: &T) -> Result<()> {
    let json = serde_json::to_string(msg).context("failed to serialize message")?;
    writer.write_all(json.as_bytes()).await.context("failed to write message")?;
    writer.write_all(b"\0").await.context("failed to write null terminator")?;
    Ok(())
}

/// Receive a null-terminated JSON message
pub async fn recv_msg<T: for<'de> Deserialize<'de>, R: AsyncRead + Unpin>(
    reader: &mut R,
    buf: &mut Vec<u8>,
) -> Result<Option<T>> {
    loop {
        if let Some(pos) = buf.iter().position(|&b| b == 0) {
            let msg_bytes = buf[..pos].to_vec();
            buf.drain(..=pos);
            let msg: T = serde_json::from_slice(&msg_bytes)
                .with_context(|| format!("failed to parse message: {:?}", String::from_utf8_lossy(&msg_bytes)))?;
            return Ok(Some(msg));
        }

        let mut tmp = [0u8; 4096];
        let n = reader.read(&mut tmp).await.context("failed to read from socket")?;
        if n == 0 {
            if buf.is_empty() {
                return Ok(None);
            }
            return Err(anyhow::anyhow!("connection closed mid-message"));
        }
        buf.extend_from_slice(&tmp[..n]);
    }
}
RUST

