//! Server-side implementation

use std::collections::HashMap;
use std::net::{IpAddr, SocketAddr};
use std::sync::Arc;
use std::time::Duration;

use anyhow::{bail, Context, Result};
use tokio::io::copy_bidirectional;
use tokio::net::{TcpListener, TcpStream};
use tokio::sync::{oneshot, Mutex};
use tokio::time::interval;
use tracing::{info, warn, Span};
use uuid::Uuid;

use crate::shared::*;

/// State shared across control connections
struct ServerState {
    /// Pending proxy connections waiting to be accepted by clients
    pending: HashMap<Uuid, oneshot::Sender<TcpStream>>,
}

impl ServerState {
    fn new() -> Self {
        ServerState {
            pending: HashMap::new(),
        }
    }
}

/// Server configuration
pub struct Server {
    pub min_port: u16,
    pub max_port: u16,
    pub secret: Option<String>,
    pub bind_addr: IpAddr,
    pub bind_tunnels: Option<IpAddr>,
}

impl Server {
    /// Run the server
    pub async fn listen(self) -> Result<()> {
        let addr = SocketAddr::new(self.bind_addr, CONTROL_PORT);
        let listener = TcpListener::bind(addr)
            .await
            .with_context(|| format!("failed to bind control server to {}", addr))?;

        info!(addr = %self.bind_addr, "server listening");

        let state = Arc::new(Mutex::new(ServerState::new()));

        loop {
            let (stream, addr) = listener.accept().await.context("failed to accept connection")?;
            let state = Arc::clone(&state);
            let min_port = self.min_port;
            let max_port = self.max_port;
            let secret = self.secret.clone();
            let bind_addr = self.bind_addr;
            let bind_tunnels = self.bind_tunnels;

            tokio::spawn(async move {
                let span = tracing::info_span!("control", addr = %addr);
                let _enter = span.enter();
                info!("incoming connection");

                if let Err(e) = handle_connection(
                    stream, addr, state, min_port, max_port, secret, bind_addr, bind_tunnels
                ).await {
                    tracing::debug!("connection error: {}", e);
                }
                info!("connection exited");
            });
        }
    }
}

async fn handle_connection(
    mut stream: TcpStream,
    addr: SocketAddr,
    state: Arc<Mutex<ServerState>>,
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: IpAddr,
    bind_tunnels: Option<IpAddr>,
) -> Result<()> {
    let mut buf = Vec::new();

    // Authentication handshake
    if let Some(ref secret) = secret {
        let challenge = Uuid::new_v4();
        send_msg(&mut stream, &ChallengeMsg { id: challenge }).await?;

        let msg: ClientMessage = recv_msg(&mut stream, &mut buf)
            .await?
            .ok_or_else(|| anyhow::anyhow!("connection closed during handshake"))?;

        match msg {
            ClientMessage::Authenticate(auth) => {
                if !verify_auth_token(secret, challenge, &auth.token) {
                    send_msg(&mut stream, &ErrorMsg { message: "invalid secret".to_string() }).await?;
                    warn!(err = "invalid secret", "server handshake failed");
                    return Ok(());
                }
            }
            _ => {
                send_msg(&mut stream, &ErrorMsg { message: "server requires secret, but no secret was provided".to_string() }).await?;
                warn!(err = "server requires secret, but no secret was provided", "server handshake failed");
                return Ok(());
            }
        }
    } else {
        // Check if client is sending auth when we don't require it
        // Actually, we just wait for Hello or Accept
    }

    // Read the first client message (could be Hello or Accept)
    let msg: ClientMessage = recv_msg(&mut stream, &mut buf)
        .await?
        .ok_or_else(|| anyhow::anyhow!("connection closed"))?;

    match msg {
        ClientMessage::Hello(hello) => {
            // New client requesting a tunnel
            let port = hello.port;
            handle_hello(stream, buf, addr, state, min_port, max_port, port, bind_addr, bind_tunnels).await
        }
        ClientMessage::Accept(accept) => {
            // Client is accepting a proxy connection
            handle_accept(stream, accept.id, state).await
        }
        ClientMessage::Authenticate(_) => {
            // Got auth when none required
            warn!(err = "server requires secret, but no secret was provided", "server handshake failed");
            Err(anyhow::anyhow!("unexpected authenticate message"))
        }
    }
}

async fn handle_hello(
    mut stream: TcpStream,
    _buf: Vec<u8>,
    addr: SocketAddr,
    state: Arc<Mutex<ServerState>>,
    min_port: u16,
    max_port: u16,
    requested_port: u16,
    bind_addr: IpAddr,
    bind_tunnels: Option<IpAddr>,
) -> Result<()> {
    let tunnel_bind = bind_tunnels.unwrap_or(bind_addr);

    // Try to bind to the requested port
    let listener = if requested_port == 0 {
        // Random port
        let tunnel_addr = SocketAddr::new(tunnel_bind, 0);
        TcpListener::bind(tunnel_addr)
            .await
            .with_context(|| "failed to bind tunnel listener")?
    } else {
        // Check port range
        if requested_port < min_port || requested_port > max_port {
            send_msg(&mut stream, &ErrorMsg { message: "client port number not in allowed range".to_string() }).await?;
            bail!("port out of range: {}", requested_port);
        }

        let tunnel_addr = SocketAddr::new(tunnel_bind, requested_port);
        match TcpListener::bind(tunnel_addr).await {
            Ok(l) => l,
            Err(e) if e.kind() == std::io::ErrorKind::AddrInUse => {
                send_msg(&mut stream, &ErrorMsg { message: "port already in use".to_string() }).await?;
                bail!("port already in use: {}", requested_port);
            }
            Err(e) => {
                send_msg(&mut stream, &ErrorMsg { message: format!("failed to bind port: {}", e) }).await?;
                bail!("failed to bind port: {}", e);
            }
        }
    };

    let port = listener.local_addr()?.port();
    info!(host = %tunnel_bind, port = port, "new client");

    // Send back the hello with the assigned port
    send_msg(&mut stream, &HelloMsg { port }).await?;

    // Send first heartbeat immediately
    send_msg(&mut stream, &"Heartbeat").await?;

    // Accept incoming connections and notify client
    let state_clone = Arc::clone(&state);
    let mut heartbeat = interval(Duration::from_millis(500));
    heartbeat.tick().await; // Skip first tick (immediate)

    loop {
        tokio::select! {
            result = listener.accept() => {
                match result {
                    Ok((incoming, incoming_addr)) => {
                        info!(addr = %incoming_addr, port = port, "new connection");

                        let id = Uuid::new_v4();
                        let (tx, rx) = oneshot::channel();

                        {
                            let mut s = state_clone.lock().await;
                            s.pending.insert(id, tx);
                        }

                        // Notify client about the new connection
                        send_msg(&mut stream, &ConnectionMsg { id }).await?;

                        // Wait for client to accept
                        let state_for_cleanup = Arc::clone(&state_clone);
                        tokio::spawn(async move {
                            match tokio::time::timeout(Duration::from_secs(10), rx).await {
                                Ok(Ok(mut client_stream)) => {
                                    let mut incoming_mut = incoming;
                                    if let Err(e) = copy_bidirectional(&mut incoming_mut, &mut client_stream).await {
                                        tracing::debug!("proxy error: {}", e);
                                    }
                                }
                                Ok(Err(_)) => {
                                    // Channel was dropped
                                }
                                Err(_) => {
                                    // Timeout
                                    let mut s = state_for_cleanup.lock().await;
                                    s.pending.remove(&id);
                                }
                            }
                        });
                    }
                    Err(e) => {
