                                Ok(Ok(mut client_stream)) => {
                                    let mut incoming_mut = incoming;
                                    if let Err(e) = copy_bidirectional(&mut incoming_mut, &mut client_stream).await {
                                        tracing::debug!("proxy error: {}", e);
                                    }
                                }
                                Ok(Err(_)) => {
                                    // Channel was dropped
                                }
                                Err(_) => {
                                    // Timeout
                                    let mut s = state_for_cleanup.lock().await;
                                    s.pending.remove(&id);
                                }
                            }
                        });
                    }
                    Err(e) => {
                        bail!("failed to accept tunnel connection: {}", e);
                    }
                }
            }
            _ = heartbeat.tick() => {
                send_msg(&mut stream, &"Heartbeat").await?;
            }
        }
    }
}

async fn handle_accept(
    stream: TcpStream,
    id: Uuid,
    state: Arc<Mutex<ServerState>>,
) -> Result<()> {
    info!(id = %id, "forwarding connection");

    let tx = {
        let mut s = state.lock().await;
        s.pending.remove(&id)
    };

    match tx {
        Some(tx) => {
            let _ = tx.send(stream);
        }
        None => {
            tracing::debug!("no pending connection for id: {}", id);
        }
    }

    Ok(())
}
