mod client;
mod server;
mod shared;

use std::net::IpAddr;

use anyhow::Result;
use clap::{Parser, Subcommand};
use tracing_subscriber::EnvFilter;

#[derive(Parser, Debug)]
#[command(name = "bore-cli", version = "0.6.0")]
#[command(about = "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.")]
struct Args {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Starts a local proxy to the remote server
    Local(LocalArgs),
    /// Runs the remote proxy server
    Server(ServerArgs),
}

#[derive(Parser, Debug)]
struct LocalArgs {
    /// The local port to expose
    #[arg(env = "BORE_LOCAL_PORT")]
    local_port: u16,

    /// The local host to expose
    #[arg(short = 'l', long = "local-host", value_name = "HOST", default_value = "localhost")]
    local_host: String,

    /// Address of the remote server to expose local ports to
    #[arg(short = 't', long = "to", value_name = "TO", env = "BORE_SERVER")]
    to: String,

    /// Optional port on the remote server to select
    #[arg(short = 'p', long = "port", value_name = "PORT", default_value = "0")]
    port: u16,

    /// Optional secret for authentication
    #[arg(short = 's', long = "secret", value_name = "SECRET", env = "BORE_SECRET")]
    secret: Option<String>,
}

#[derive(Parser, Debug)]
struct ServerArgs {
    /// Minimum accepted TCP port number
    #[arg(long = "min-port", value_name = "MIN_PORT", env = "BORE_MIN_PORT", default_value = "1024")]
    min_port: u16,

    /// Maximum accepted TCP port number
    #[arg(long = "max-port", value_name = "MAX_PORT", env = "BORE_MAX_PORT", default_value = "65535")]
    max_port: u16,

    /// Optional secret for authentication
    #[arg(short = 's', long = "secret", value_name = "SECRET", env = "BORE_SECRET")]
    secret: Option<String>,

    /// IP address to bind to, clients must reach this
    #[arg(long = "bind-addr", value_name = "BIND_ADDR", default_value = "0.0.0.0")]
    bind_addr: IpAddr,

    /// IP address where tunnels will listen on, defaults to --bind-addr
    #[arg(long = "bind-tunnels", value_name = "BIND_TUNNELS")]
    bind_tunnels: Option<IpAddr>,
}

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize logging
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();

    match args.command {
        Commands::Local(local_args) => {
            let client = client::Client {
                local_host: local_args.local_host,
                local_port: local_args.local_port,
                server: local_args.to,
                remote_port: local_args.port,
                secret: local_args.secret,
            };
            client.listen().await?;
        }
        Commands::Server(server_args) => {
            let server = server::Server {
                min_port: server_args.min_port,
                max_port: server_args.max_port,
                secret: server_args.secret,
                bind_addr: server_args.bind_addr,
                bind_tunnels: server_args.bind_tunnels,
            };
            server.listen().await?;
        }
    }

    Ok(())
}
