	fmt.Println("Usage: bore-cli local [OPTIONS] --to <TO> <LOCAL_PORT>")
	fmt.Println()
	fmt.Println("Arguments:")
	fmt.Println("  <LOCAL_PORT>  The local port to expose [env: BORE_LOCAL_PORT=]")
	fmt.Println()
	fmt.Println("Options:")
	fmt.Println("  -l, --local-host <HOST>  The local host to expose [default: localhost]")
	fmt.Println("  -t, --to <TO>            Address of the remote server to expose local ports to [env: BORE_SERVER=]")
	fmt.Println("  -p, --port <PORT>        Optional port on the remote server to select [default: 0]")
	fmt.Println("  -s, --secret <SECRET>    Optional secret for authentication [env: BORE_SECRET]")
