}

func printServerHelp() {
	fmt.Println("Runs the remote proxy server")
	fmt.Println()
	fmt.Println("Usage: bore-cli server [OPTIONS]")
	fmt.Println()
	fmt.Println("Options:")
	fmt.Println("      --min-port <MIN_PORT>          Minimum accepted TCP port number [env: BORE_MIN_PORT=] [default: 1024]")
