		if p, err := strconv.ParseUint(v, 10, 16); err == nil {
			config.MaxPort = uint16(p)
		}
	}
	if v := os.Getenv("BORE_SECRET"); v != "" {
		config.Secret = v
		config.HasSecret = true
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "--help" || arg == "-h":
			printServerHelp()
			os.Exit(0)
		case arg == "--min-port":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --min-port requires a value")
				os.Exit(1)
			}
			p, err := strconv.ParseUint(args[i], 10, 16)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--min-port'\n", args[i])
				os.Exit(1)
			}
			config.MinPort = uint16(p)
		case strings.HasPrefix(arg, "--min-port="):
			p, err := strconv.ParseUint(strings.TrimPrefix(arg, "--min-port="), 10, 16)
			if err != nil {
				fmt.Fprintln(os.Stderr, "error: invalid min-port value")
				os.Exit(1)
			}
			config.MinPort = uint16(p)
		case arg == "--max-port":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --max-port requires a value")
				os.Exit(1)
			}
			p, err := strconv.ParseUint(args[i], 10, 16)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--max-port'\n", args[i])
				os.Exit(1)
			}
			config.MaxPort = uint16(p)
		case strings.HasPrefix(arg, "--max-port="):
			p, err := strconv.ParseUint(strings.TrimPrefix(arg, "--max-port="), 10, 16)
			if err != nil {
				fmt.Fprintln(os.Stderr, "error: invalid max-port value")
				os.Exit(1)
			}
			config.MaxPort = uint16(p)
		case arg == "-s" || arg == "--secret":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --secret requires a value")
				os.Exit(1)
			}
			config.Secret = args[i]
			config.HasSecret = true
		case strings.HasPrefix(arg, "--secret="):
			config.Secret = strings.TrimPrefix(arg, "--secret=")
			config.HasSecret = true
		case arg == "--bind-addr":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --bind-addr requires a value")
				os.Exit(1)
			}
			// Validate IP
			if net.ParseIP(args[i]) == nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--bind-addr <BIND_ADDR>': invalid IP address syntax\n\nFor more information, try '--help'.\n", args[i])
				os.Exit(1)
			}
			config.BindAddr = args[i]
		case strings.HasPrefix(arg, "--bind-addr="):
			addr := strings.TrimPrefix(arg, "--bind-addr=")
			if net.ParseIP(addr) == nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--bind-addr <BIND_ADDR>': invalid IP address syntax\n\nFor more information, try '--help'.\n", addr)
				os.Exit(1)
			}
			config.BindAddr = addr
		case arg == "--bind-tunnels":
			i++
			if i >= len(args) {
				fmt.Fprintln(os.Stderr, "error: --bind-tunnels requires a value")
				os.Exit(1)
			}
			if net.ParseIP(args[i]) == nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--bind-tunnels <BIND_TUNNELS>': invalid IP address syntax\n\nFor more information, try '--help'.\n", args[i])
				os.Exit(1)
			}
			config.BindTunnels = args[i]
		case strings.HasPrefix(arg, "--bind-tunnels="):
			addr := strings.TrimPrefix(arg, "--bind-tunnels=")
			if net.ParseIP(addr) == nil {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--bind-tunnels <BIND_TUNNELS>': invalid IP address syntax\n\nFor more information, try '--help'.\n", addr)
