// UUID type
type UUID [16]byte

func newUUID() UUID {
	var u UUID
	rand.Read(u[:])
	// Set version 4
	u[6] = (u[6] & 0x0f) | 0x40
	// Set variant bits
	u[8] = (u[8] & 0x3f) | 0x80
	return u
}

func (u UUID) String() string {
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
		u[0:4], u[4:6], u[6:8], u[8:10], u[10:16])
}

func uuidFromString(s string) (UUID, error) {
	s = strings.ReplaceAll(s, "-", "")
	b, err := hex.DecodeString(s)
	if err != nil {
		return UUID{}, err
	}
	if len(b) != 16 {
		return UUID{}, fmt.Errorf("invalid UUID length")
	}
	var u UUID
	copy(u[:], b)
	return u, nil
}

func (u UUID) MarshalJSON() ([]byte, error) {
	return json.Marshal(u.String())
}

func (u *UUID) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	parsed, err := uuidFromString(s)
	if err != nil {
		return err
	}
	*u = parsed
	return nil
}

// Protocol messages - server to client
type ServerMessage struct {
	Type       string
	Challenge  *UUID
	Hello      *uint16
	Connection *UUID
	Error      *string
	Heartbeat  bool
}

func (m *ServerMessage) UnmarshalJSON(data []byte) error {
	// Try "Heartbeat"
	var heartbeat string
	if err := json.Unmarshal(data, &heartbeat); err == nil && heartbeat == "Heartbeat" {
		m.Type = "Heartbeat"
		m.Heartbeat = true
		return nil
	}

	var obj map[string]json.RawMessage
	if err := json.Unmarshal(data, &obj); err != nil {
		return err
	}

	if v, ok := obj["Challenge"]; ok {
		var id UUID
		if err := json.Unmarshal(v, &id); err != nil {
			return err
		}
		m.Type = "Challenge"
		m.Challenge = &id
	} else if v, ok := obj["Hello"]; ok {
		var port uint16
		if err := json.Unmarshal(v, &port); err != nil {
			return err
		}
		m.Type = "Hello"
		m.Hello = &port
	} else if v, ok := obj["Connection"]; ok {
		var id UUID
		if err := json.Unmarshal(v, &id); err != nil {
			return err
		}
		m.Type = "Connection"
		m.Connection = &id
	} else if v, ok := obj["Error"]; ok {
		var msg string
		if err := json.Unmarshal(v, &msg); err != nil {
			return err
		}
		m.Type = "Error"
		m.Error = &msg
	}
	return nil
}

// ClientMessage - client to server
type ClientMessage struct {
	Authenticate *string
	Hello        *uint16
	Accept       *UUID
}

func (m *ClientMessage) UnmarshalJSON(data []byte) error {
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(data, &obj); err != nil {
		return err
	}

	if v, ok := obj["Authenticate"]; ok {
		var token string
		if err := json.Unmarshal(v, &token); err != nil {
			return err
		}
		m.Authenticate = &token
	} else if v, ok := obj["Hello"]; ok {
		var port uint16
		if err := json.Unmarshal(v, &port); err != nil {
			return err
		}
		m.Hello = &port
	} else if v, ok := obj["Accept"]; ok {
		var id UUID
		if err := json.Unmarshal(v, &id); err != nil {
			return err
		}
		m.Accept = &id
	}
	return nil
}

// Compute HMAC-SHA256(key=SHA256(secret), msg=challenge_uuid_bytes)
func computeAuthToken(secret string, challenge UUID) string {
	secretKey := sha256.Sum256([]byte(secret))
	mac := hmac.New(sha256.New, secretKey[:])
	mac.Write(challenge[:])
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyAuthToken(secret string, challenge UUID, token string) bool {
	expected := computeAuthToken(secret, challenge)
	return expected == token
}

// Send a null-terminated JSON message
func sendMsg(conn net.Conn, v interface{}) error {
	var jsonBytes []byte
	var err error

	// Special case for "Heartbeat" string
	if s, ok := v.(string); ok && s == "Heartbeat" {
		jsonBytes = []byte(`"Heartbeat"`)
	} else {
		jsonBytes, err = json.Marshal(v)
		if err != nil {
			return err
		}
	}

	_, err = conn.Write(append(jsonBytes, 0))
	return err
}

// Connection with buffer for reading null-terminated messages
type ConnReader struct {
	conn net.Conn
	buf  []byte
}

func newConnReader(conn net.Conn) *ConnReader {
	return &ConnReader{conn: conn, buf: make([]byte, 0, 4096)}
}

func (cr *ConnReader) recvMsg(v interface{}) error {
	for {
		for i, b := range cr.buf {
			if b == 0 {
				msgBytes := make([]byte, i)
				copy(msgBytes, cr.buf[:i])
				cr.buf = cr.buf[i+1:]
				return json.Unmarshal(msgBytes, v)
			}
		}

		tmp := make([]byte, 4096)
		n, err := cr.conn.Read(tmp)
		if err != nil {
			return err
		}
		cr.buf = append(cr.buf, tmp[:n]...)
	}
}

// Server implementation
type ServerConfig struct {
	MinPort     uint16
	MaxPort     uint16
	Secret      string
	HasSecret   bool
	BindAddr    string
	BindTunnels string
}

type serverState struct {
	mu      sync.Mutex
	pending map[UUID]chan net.Conn
}

func newServerState() *serverState {
	return &serverState{
		pending: make(map[UUID]chan net.Conn),
	}
}

func (s *serverState) registerPending(id UUID) chan net.Conn {
	ch := make(chan net.Conn, 1)
	s.mu.Lock()
	s.pending[id] = ch
	s.mu.Unlock()
	return ch
}

func (s *serverState) claimPending(id UUID) chan net.Conn {
	s.mu.Lock()
	ch, ok := s.pending[id]
	if ok {
		delete(s.pending, id)
	}
	s.mu.Unlock()
	if ok {
		return ch
	}
	return nil
}

func (s *serverState) cancelPending(id UUID) {
	s.mu.Lock()
	delete(s.pending, id)
	s.mu.Unlock()
}

func runServer(config ServerConfig) error {
	bindAddr := config.BindAddr
	addr := net.JoinHostPort(bindAddr, strconv.Itoa(CONTROL_PORT))

	listener, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("Address already in use (os error 98)")
	}

	logInfo(nil, "bore_cli::server", "server listening", [2]string{"addr", bindAddr})

	state := newServerState()

	for {
		conn, err := listener.Accept()
		if err != nil {
			return err
		}

		go func(c net.Conn) {
			remoteAddr := c.RemoteAddr().String()
			span := &SpanCtx{
				name:   "control",
				fields: [][2]string{{"addr", remoteAddr}},
			}
			logInfo(span, "bore_cli::server", "incoming connection")

			if err := handleServerConn(c, remoteAddr, state, config, span); err != nil {
				// Log debug errors (connection closed etc)
			}
			logInfo(span, "bore_cli::server", "connection exited")
		}(conn)
	}
}

func handleServerConn(conn net.Conn, remoteAddr string, state *serverState, config ServerConfig, span *SpanCtx) error {
	defer conn.Close()

	reader := newConnReader(conn)

	// Authentication
	if config.HasSecret {
		challenge := newUUID()
		challengeMsg := map[string]interface{}{"Challenge": challenge}
		if err := sendMsg(conn, challengeMsg); err != nil {
			return err
		}

		var clientMsg ClientMessage
		if err := reader.recvMsg(&clientMsg); err != nil {
			logWarn(span, "bore_cli::server", "server handshake failed", [2]string{"err", "connection closed"})
			return err
		}

		if clientMsg.Authenticate == nil {
			errMsg := map[string]string{"Error": "server requires secret, but no secret was provided"}
			sendMsg(conn, errMsg)
			logWarn(span, "bore_cli::server", "server handshake failed", [2]string{"err", "server requires secret, but no secret was provided"})
			return fmt.Errorf("no auth provided")
		}

		if !verifyAuthToken(config.Secret, challenge, *clientMsg.Authenticate) {
			errMsg := map[string]string{"Error": "invalid secret"}
			sendMsg(conn, errMsg)
			logWarn(span, "bore_cli::server", "server handshake failed", [2]string{"err", "invalid secret"})
			return fmt.Errorf("invalid secret")
		}
	}

	// Read Hello or Accept
	var clientMsg ClientMessage
	if err := reader.recvMsg(&clientMsg); err != nil {
		return err
	}

	if clientMsg.Hello != nil {
		return handleHello(conn, reader, remoteAddr, state, config, *clientMsg.Hello, span)
	} else if clientMsg.Accept != nil {
		return handleAccept(conn, *clientMsg.Accept, state, span)
	} else if clientMsg.Authenticate != nil {
		// Auth when not required
		logWarn(span, "bore_cli::server", "server handshake failed", [2]string{"err", "server requires secret, but no secret was provided"})
		return fmt.Errorf("unexpected auth message")
	}

	return fmt.Errorf("unexpected message")
}

func handleHello(conn net.Conn, reader *ConnReader, remoteAddr string, state *serverState, config ServerConfig, requestedPort uint16, span *SpanCtx) error {
	tunnelBind := config.BindTunnels
	if tunnelBind == "" {
		tunnelBind = config.BindAddr
	}

	var tunnelListener net.Listener
	var err error

	if requestedPort == 0 {
		tunnelAddr := net.JoinHostPort(tunnelBind, "0")
		tunnelListener, err = net.Listen("tcp", tunnelAddr)
		if err != nil {
			return fmt.Errorf("failed to bind tunnel: %w", err)
		}
	} else {
		if requestedPort < config.MinPort || requestedPort > config.MaxPort {
			errMsg := map[string]string{"Error": "client port number not in allowed range"}
			sendMsg(conn, errMsg)
			return fmt.Errorf("port out of range: %d", requestedPort)
		}

		tunnelAddr := net.JoinHostPort(tunnelBind, strconv.Itoa(int(requestedPort)))
		tunnelListener, err = net.Listen("tcp", tunnelAddr)
		if err != nil {
			errMsg := map[string]string{"Error": "port already in use"}
			sendMsg(conn, errMsg)
			return fmt.Errorf("port already in use: %d", requestedPort)
		}
	}
	defer tunnelListener.Close()

	actualPort := tunnelListener.Addr().(*net.TCPAddr).Port

	logInfo(span, "bore_cli::server", "new client",
		[2]string{"host", tunnelBind},
		[2]string{"port", strconv.Itoa(actualPort)})

	// Send Hello back
	helloMsg := map[string]interface{}{"Hello": actualPort}
	if err := sendMsg(conn, helloMsg); err != nil {
		return err
	}

	// Send first heartbeat
	if err := sendMsg(conn, "Heartbeat"); err != nil {
		return err
	}

	// Channel for tunnel connections
	tunnelConns := make(chan net.Conn, 10)
	tunnelErrors := make(chan error, 1)

	go func() {
		for {
			tc, err := tunnelListener.Accept()
			if err != nil {
				tunnelErrors <- err
				return
			}
			tunnelConns <- tc
		}
	}()

	// Write mutex
	writeMu := &sync.Mutex{}
	sendSafe := func(v interface{}) error {
		writeMu.Lock()
		defer writeMu.Unlock()
		return sendMsg(conn, v)
	}

	heartbeatTicker := time.NewTicker(500 * time.Millisecond)
	defer heartbeatTicker.Stop()

	for {
		select {
		case tc := <-tunnelConns:
			incomingAddr := tc.RemoteAddr().String()
			logInfo(span, "bore_cli::server", "new connection",
				[2]string{"addr", incomingAddr},
				[2]string{"port", strconv.Itoa(actualPort)})

			id := newUUID()
			ch := state.registerPending(id)

			connMsg := map[string]interface{}{"Connection": id}
			if err := sendSafe(connMsg); err != nil {
				tc.Close()
				state.cancelPending(id)
				return err
			}

			go func(id UUID, tc net.Conn, ch chan net.Conn) {
				select {
				case clientConn, ok := <-ch:
					if ok {
						done := make(chan struct{}, 2)
						go func() {
							io.Copy(tc, clientConn)
							tc.CloseWrite()
							done <- struct{}{}
						}()
						go func() {
							io.Copy(clientConn, tc)
							if cw, ok := clientConn.(interface{ CloseWrite() error }); ok {
								cw.CloseWrite()
							}
							done <- struct{}{}
						}()
						<-done
						<-done
						tc.Close()
						clientConn.Close()
					} else {
						tc.Close()
					}
				case <-time.After(10 * time.Second):
					state.cancelPending(id)
					tc.Close()
				}
			}(id, tc, ch)

		case err := <-tunnelErrors:
			return fmt.Errorf("tunnel listener error: %w", err)

		case <-heartbeatTicker.C:
			if err := sendSafe("Heartbeat"); err != nil {
				return err
			}
		}
	}
}

func handleAccept(conn net.Conn, id UUID, state *serverState, span *SpanCtx) error {
	defer conn.Close()

	logInfo(span, "bore_cli::server", "forwarding connection", [2]string{"id", id.String()})

	ch := state.claimPending(id)
	if ch != nil {
		ch <- conn
		// Don't close conn here - the goroutine handling the pipe will close it
		// But we've transferred ownership, so prevent the defer from running
		// Actually the defer will run but by then the goroutine owns the conn
		// Let me not defer close here...
	}

	return nil
}

// Client implementation
type ClientConfig struct {
	LocalHost  string
	LocalPort  uint16
	Server     string
	RemotePort uint16
	Secret     string
	HasSecret  bool
}

func runClient(config ClientConfig) error {
	serverAddr := fmt.Sprintf("%s:%d", config.Server, CONTROL_PORT)

	conn, err := net.Dial("tcp", serverAddr)
	if err != nil {
		return fmt.Errorf("could not connect to %s\n\nCaused by:\n    %w", serverAddr, err)
	}
	defer conn.Close()

	reader := newConnReader(conn)

	// Authentication
	if config.HasSecret {
		var serverMsg ServerMessage
		if err := reader.recvMsg(&serverMsg); err != nil {
			return err
		}

		if serverMsg.Type == "Challenge" {
			token := computeAuthToken(config.Secret, *serverMsg.Challenge)
			authMsg := map[string]string{"Authenticate": token}
			if err := sendMsg(conn, authMsg); err != nil {
				return err
			}
		} else if serverMsg.Type == "Error" {
			return fmt.Errorf(*serverMsg.Error)
		} else {
			return fmt.Errorf("unexpected message during auth")
		}
	}

	// Send Hello
	helloMsg := map[string]interface{}{"Hello": config.RemotePort}
	if err := sendMsg(conn, helloMsg); err != nil {
		return err
	}

	// Read Hello response
	var serverMsg ServerMessage
	if err := reader.recvMsg(&serverMsg); err != nil {
		return err
	}

	var remotePort uint16
	switch serverMsg.Type {
	case "Hello":
		remotePort = *serverMsg.Hello
	case "Error":
		return fmt.Errorf("server error: %s", *serverMsg.Error)
	default:
		return fmt.Errorf("unexpected message from server")
	}

	logInfo(nil, "bore_cli::client", "connected to server",
		[2]string{"remote_port", strconv.Itoa(int(remotePort))})
	logInfo(nil, "bore_cli::client",
		fmt.Sprintf("listening at %s:%d", config.Server, remotePort))

	// Main loop
	for {
		var msg ServerMessage
		if err := reader.recvMsg(&msg); err != nil {
			return fmt.Errorf("connection closed: %w", err)
		}

		switch msg.Type {
		case "Connection":
			id := *msg.Connection
			go proxyConnection(config, id)
		case "Heartbeat":
			// ignore
		case "Error":
			return fmt.Errorf("server error: %s", *msg.Error)
		}
	}
}

func proxyConnection(config ClientConfig, id UUID) {
	proxySpan := &SpanCtx{
		name:   "proxy",
		fields: [][2]string{{"id", id.String()}},
	}
	logInfo(proxySpan, "bore_cli::client", "new connection")

	if err := doProxy(config, id); err != nil {
		logWarn(proxySpan, "bore_cli::client", "connection exited with error", [2]string{"err", err.Error()})
	} else {
		logInfo(proxySpan, "bore_cli::client", "connection exited")
	}
}

func doProxy(config ClientConfig, id UUID) error {
	// Connect to local service
	localAddr := fmt.Sprintf("%s:%d", config.LocalHost, config.LocalPort)
	localConn, err := net.Dial("tcp", localAddr)
	if err != nil {
		return fmt.Errorf("could not connect to %s", localAddr)
	}
	defer localConn.Close()

	// Connect to server
	serverAddr := fmt.Sprintf("%s:%d", config.Server, CONTROL_PORT)
	serverConn, err := net.Dial("tcp", serverAddr)
	if err != nil {
		return fmt.Errorf("could not connect to %s", serverAddr)
	}
	defer serverConn.Close()

	reader := newConnReader(serverConn)

	// Auth if needed
	if config.HasSecret {
		var serverMsg ServerMessage
		if err := reader.recvMsg(&serverMsg); err != nil {
			return err
		}

		if serverMsg.Type == "Challenge" {
			token := computeAuthToken(config.Secret, *serverMsg.Challenge)
			authMsg := map[string]string{"Authenticate": token}
			if err := sendMsg(serverConn, authMsg); err != nil {
				return err
			}
		} else if serverMsg.Type == "Error" {
			return fmt.Errorf(*serverMsg.Error)
		} else {
			return fmt.Errorf("unexpected message during proxy auth")
		}
	}

	// Send Accept
	acceptMsg := map[string]interface{}{"Accept": id}
	if err := sendMsg(serverConn, acceptMsg); err != nil {
		return err
	}

	// Pipe data between local and server
	// Note: if there's buffered data from auth exchange, prepend it
	var serverReader io.Reader = serverConn
	if len(reader.buf) > 0 {
		serverReader = io.MultiReader(strings.NewReader(string(reader.buf)), serverConn)
		reader.buf = nil
	}

	done := make(chan struct{}, 2)
	go func() {
		io.Copy(localConn, serverReader)
		if tc, ok := localConn.(*net.TCPConn); ok {
			tc.CloseWrite()
		}
		done <- struct{}{}
	}()
	go func() {
		io.Copy(serverConn, localConn)
		if tc, ok := serverConn.(*net.TCPConn); ok {
			tc.CloseWrite()
		}
		done <- struct{}{}
	}()
	<-done
	<-done

	return nil
}

// CLI parsing
func printUsage() {
	fmt.Print("A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.\n\nUsage: bore-cli <COMMAND>\n\nCommands:\n  local   Starts a local proxy to the remote server\n  server  Runs the remote proxy server\n  help    Print this message or the help of the given subcommand(s)\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n")
}

func printLocalHelp() {
	fmt.Print("Starts a local proxy to the remote server\n\nUsage: bore-cli local [OPTIONS] --to <TO> <LOCAL_PORT>\n\nArguments:\n  <LOCAL_PORT>  The local port to expose [env: BORE_LOCAL_PORT=]\n\nOptions:\n  -l, --local-host <HOST>  The local host to expose [default: localhost]\n  -t, --to <TO>            Address of the remote server to expose local ports to [env: BORE_SERVER=]\n  -p, --port <PORT>        Optional port on the remote server to select [default: 0]\n  -s, --secret <SECRET>    Optional secret for authentication [env: BORE_SECRET]\n  -h, --help               Print help\n")
}

func printServerHelp() {
	fmt.Print("Runs the remote proxy server\n\nUsage: bore-cli server [OPTIONS]\n\nOptions:\n      --min-port <MIN_PORT>          Minimum accepted TCP port number [env: BORE_MIN_PORT=] [default: 1024]\n      --max-port <MAX_PORT>          Maximum accepted TCP port number [env: BORE_MAX_PORT=] [default: 65535]\n  -s, --secret <SECRET>              Optional secret for authentication [env: BORE_SECRET]\n      --bind-addr <BIND_ADDR>        IP address to bind to, clients must reach this [default: 0.0.0.0]\n      --bind-tunnels <BIND_TUNNELS>  IP address where tunnels will listen on, defaults to --bind-addr\n  -h, --help                         Print help\n")
}

func main() {
	args := os.Args[1:]

	if len(args) == 0 {
		printUsage()
		os.Exit(0)
	}

	switch args[0] {
	case "--help", "-h":
		printUsage()
	case "help":
		if len(args) > 1 {
			switch args[1] {
			case "local":
				printLocalHelp()
			case "server":
				printServerHelp()
			default:
				printUsage()
			}
		} else {
			printUsage()
		}
	case "--version", "-V":
		fmt.Printf("bore-cli %s\n", VERSION)
	case "local":
		parseAndRunLocal(args[1:])
	case "server":
		parseAndRunServer(args[1:])
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nFor more information, try '--help'.\n", args[0])
		os.Exit(1)
	}
}

