	sb := &strings.Builder{}

	// Timestamp
	sb.WriteString(dim + ts + reset)
	sb.WriteString(" ")

	// Level
	switch level {
	case LevelInfo:
		sb.WriteString(green + " INFO" + reset)
	case LevelWarn:
		sb.WriteString(yellow + " WARN" + reset)
	}
	sb.WriteString(" ")

