# Add a function to format errors in Rust style
rust_error_func = '''
// Format an error in Rust anyhow style
func formatRustError(err error) string {
	if err == nil {
		return ""
	}

	msg := err.Error()

	// Convert Go network errors to Rust-style OS errors
	// Go: "dial tcp host:port: connect: connection refused"
	// Rust: "Connection refused (os error 111)"

	// Check for syscall errors
	var opErr *net.OpError
	if errors.As(err, &opErr) {
		var syscallErr *os.SyscallError
		if errors.As(opErr.Err, &syscallErr) {
			errno := syscallErr.Err.(syscall.Errno)
			return fmt.Sprintf("%s (os error %d)", osErrorName(errno), int(errno))
		}
		// Check for direct syscall.Errno
		var sysErrno syscall.Errno
		if errors.As(opErr.Err, &sysErrno) {
			return fmt.Sprintf("%s (os error %d)", osErrorName(sysErrno), int(sysErrno))
		}
	}

	// Fallback: use the raw message
	return msg
}

// Convert syscall errno to human-readable name (matches Rust's OS error names)
func osErrorName(errno syscall.Errno) string {
	switch errno {
	case syscall.ECONNREFUSED:
		return "Connection refused"
	case syscall.ETIMEDOUT:
		return "Connection timed out"
	case syscall.ECONNRESET:
		return "Connection reset by peer"
	case syscall.ENETUNREACH:
		return "Network unreachable"
	case syscall.EHOSTUNREACH:
		return "No route to host"
	case syscall.EADDRINUSE:
		return "Address already in use"
	case syscall.EPERM:
		return "Permission denied"
	case syscall.ENOENT:
		return "No such file or directory"
	default:
		return errno.Error()
	}
}

// Format a "could not connect to {addr}" error like Rust's anyhow
func connectError(addr string, err error) error {
	cause := formatRustError(err)
	return fmt.Errorf("could not connect to %s\\n\\nCaused by:\\n    %s", addr, cause)
}
'''

