	if err == nil {
		return ""
	}

	msg := err.Error()

	// Convert Go network errors to Rust-style OS errors
	// Go: "dial tcp host:port: connect: connection refused"
	// Rust: "Connection refused (os error 111)"

	// Check for syscall errors
	var opErr *net.OpError
	if errors.As(err, &opErr) {
		var syscallErr *os.SyscallError
		if errors.As(opErr.Err, &syscallErr) {
