		var sysErrno syscall.Errno
		if errors.As(opErr.Err, &sysErrno) {
			return fmt.Sprintf("%s (os error %d)", osErrorName(sysErrno), int(sysErrno))
		}
	}

	// Fallback: use the raw message
	return msg
}'''

